package com.costeo3d.infrastructure.persistence.dao;

import java.util.List;
import java.util.Optional;

import com.costeo3d.domain.model.Quote;

/** Persistence contract for complete quotes and their historical details. */
public interface QuoteDao {

    // Inserts the quote, its items and their materials atomically.
    // Returns a new Quote with IDs generated by MySQL at every level.
    Quote insert(Quote quote);

    // Returns the complete quote, including its items and materials.
    Optional<Quote> findById(int id);

    // Returns all quotes, including their items and materials.
    List<Quote> findAll();

    // Only persists the quote's current status; never alters historical amounts.
    // Returns false when the quote does not exist.
    boolean updateStatus(Quote quote);
}
